import subprocess, sys, re, os

REPO = sys.argv[1] if len(sys.argv) > 1 else "/tmp/wt-main"
files = sys.argv[2:] if len(sys.argv) > 2 else None

def git(*args):
    r = subprocess.run(["git", "-C", REPO, *args], capture_output=True, text=True)
    return r.stdout, r.returncode

BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
owner = {}
for br in BRANCHES:
    out, _ = git("log", "--format=%H", f"origin/friend/{br}")
    for s in out.split():
        owner.setdefault(s, br)

body_cache = {}
def body_of(sha):
    if sha not in body_cache:
        body_cache[sha] = git("log", "-1", "--format=%B", sha)
    return body_cache[sha]

if not files:
    out, _ = git("ls-tree", "-r", "--name-only", "HEAD")
    files = [f for f in out.splitlines() if re.match(r"^S\d+/E\d+\.md$", f)]

problems = []
seen = {}
total = 0
for path in sorted(files):
    with open(os.path.join(REPO, path), encoding="utf-8") as fh:
        text = fh.read()
    blocks = re.split(r"\n(?=\*\*)", text)
    for b in blocks:
        m = re.match(r"\*\*(?P<sp>[^*]+)\*\* \((?P<ts>[^)]+)\)\n\nSource: friend/(?P<br>[a-z]+) @ (?P<sha>[0-9a-f]{40})\n\n(?P<utt>.*?)\s*$", b.strip(), re.S)
        if not m:
            continue
        total += 1
        sha = m.group("sha")
        if sha in seen:
            problems.append(f"{path}: duplicate source {sha} (also {seen[sha]})")
        seen[sha] = path
        body, rc = body_of(sha)
        if rc != 0:
            problems.append(f"{path}: {sha} not found")
            continue
        mm = re.search(r"^Reply-To:[^\n]*\n\n(.*)$", body, re.S | re.M)
        if not mm:
            problems.append(f"{path}: {sha} no Reply-To block")
            continue
        src_utt = mm.group(1).rstrip("\n")
        if m.group("utt").rstrip("\n") != src_utt:
            problems.append(f"{path}: {sha} MISMATCH")
        sp_src = re.search(r"^Speaker: (.+)$", body, re.M).group(1).strip()
        if sp_src != m.group("sp").strip():
            problems.append(f"{path}: {sha} speaker {sp_src!r} vs {m.group('sp')!r}")
        br_src = owner.get(sha)
        if br_src and br_src != m.group("br"):
            problems.append(f"{path}: {sha} branch {br_src} vs {m.group('br')}")

print(f"checked {total} entries in {len(files)} files")
print(f"PROBLEMS: {len(problems)}")
for p in problems[:30]:
    print(" -", p)
